public class HTMLPrinter {
    public static void insertPageProlog(StringBuffer buffer, int offset, RGB foreground, RGB background, String styleSheet) {}
}

package org.eclipse.jdt.internal.ui.infoviews;

public class JavadocView {
    private RGB fBackgroundColorRGB;
    private RGB fForegroundColorRGB;
    private static final RGB EXISTING_FOREGROUND_COLOR = new RGB(10, 20, 30);

    public void someMethodAlreadySettingColor(StringBuffer buffer, String fgStyleSheet) {
        // This call already passes a non-null RGB for foreground, so it should not be matched by the rule.
        HTMLPrinter.insertPageProlog(buffer, 0, EXISTING_FOREGROUND_COLOR, fBackgroundColorRGB, fgStyleSheet);
    }

    // This call is in a different class, so it should not match due to the `inClass` guard.
    public static class OtherClass {
        private RGB fBackgroundColorRGB;
        // No fForegroundColorRGB field here
        public void anotherMethod(StringBuffer buffer, String fgStyleSheet) {
            HTMLPrinter.insertPageProlog(buffer, 0, null, fBackgroundColorRGB, fgStyleSheet);
        }
    }
}
